BEGIN TRANSACTION;
CREATE TABLE alerts (
	alert_id VARCHAR NOT NULL, 
	customer_id VARCHAR NOT NULL, 
	alert_type VARCHAR NOT NULL, 
	alert_message TEXT NOT NULL, 
	created_at DATETIME, 
	alert_status VARCHAR, 
	PRIMARY KEY (alert_id), 
	FOREIGN KEY(customer_id) REFERENCES customers (customer_id)
);
CREATE TABLE audit_events (
	event_id VARCHAR NOT NULL, 
	entity_type VARCHAR NOT NULL, 
	entity_id VARCHAR NOT NULL, 
	event_type VARCHAR NOT NULL, 
	old_value TEXT, 
	new_value TEXT, 
	reason TEXT, 
	actor VARCHAR NOT NULL, 
	created_at DATETIME, 
	PRIMARY KEY (event_id)
);
CREATE TABLE beneficial_owners (
	owner_id VARCHAR NOT NULL, 
	customer_id VARCHAR NOT NULL, 
	owner_name VARCHAR NOT NULL, 
	ownership_percentage FLOAT NOT NULL, 
	PRIMARY KEY (owner_id), 
	FOREIGN KEY(customer_id) REFERENCES customers (customer_id)
);
CREATE TABLE customer_types (
	customer_type_id VARCHAR NOT NULL, 
	type_name VARCHAR NOT NULL, 
	PRIMARY KEY (customer_type_id), 
	UNIQUE (type_name)
);
CREATE TABLE customers (
	customer_id VARCHAR NOT NULL, 
	customer_type_id VARCHAR NOT NULL, 
	full_name VARCHAR NOT NULL, 
	email VARCHAR NOT NULL, 
	onboarding_status VARCHAR NOT NULL, 
	created_at DATETIME, 
	PRIMARY KEY (customer_id), 
	FOREIGN KEY(customer_type_id) REFERENCES customer_types (customer_type_id), 
	UNIQUE (email)
);
CREATE TABLE documents (
	document_id VARCHAR NOT NULL, 
	customer_id VARCHAR NOT NULL, 
	document_type VARCHAR NOT NULL, 
	issue_date DATE NOT NULL, 
	expiry_date DATE, 
	document_status VARCHAR NOT NULL, 
	holder_name VARCHAR NOT NULL, 
	PRIMARY KEY (document_id), 
	FOREIGN KEY(customer_id) REFERENCES customers (customer_id)
);
CREATE TABLE kyc_requirements (
	requirement_id VARCHAR NOT NULL, 
	customer_type_id VARCHAR NOT NULL, 
	document_type VARCHAR NOT NULL, 
	risk_level VARCHAR NOT NULL, 
	is_mandatory BOOLEAN, 
	PRIMARY KEY (requirement_id), 
	FOREIGN KEY(customer_type_id) REFERENCES customer_types (customer_type_id)
);
CREATE TABLE review_cases (
	review_id VARCHAR NOT NULL, 
	customer_id VARCHAR NOT NULL, 
	review_date DATE NOT NULL, 
	due_date DATE NOT NULL, 
	review_status VARCHAR NOT NULL, 
	resolution TEXT, 
	PRIMARY KEY (review_id), 
	FOREIGN KEY(customer_id) REFERENCES customers (customer_id)
);
CREATE TABLE risk_ratings (
	risk_id VARCHAR NOT NULL, 
	customer_id VARCHAR NOT NULL, 
	risk_level VARCHAR NOT NULL, 
	risk_score FLOAT NOT NULL, 
	assessed_at DATETIME, 
	PRIMARY KEY (risk_id), 
	UNIQUE (customer_id), 
	FOREIGN KEY(customer_id) REFERENCES customers (customer_id)
);
CREATE TABLE verifications (
	verification_id VARCHAR NOT NULL, 
	document_id VARCHAR NOT NULL, 
	verification_status VARCHAR NOT NULL, 
	verified_at DATETIME, 
	reviewer VARCHAR, 
	PRIMARY KEY (verification_id), 
	FOREIGN KEY(document_id) REFERENCES documents (document_id)
);
COMMIT;
